


export type GiftCardFundingLossDisposition = { /** RFC3339 timestamp. Format: date-time. */ "created_at": string; "disposition": "honor_value" | (string & {}); /** The whole disputed payment amount, which can include consideration for other purchases. It is separate from the original gift card consideration and honored face value. */ "dispute_amount_money": { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": "USD" | (string & {}); }; "dispute_id": string; "gift_card_funding_disposition_id": string; "gift_card_ids": Array<string>; "honored_value_money": { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": "USD" | (string & {}); }; "original_gift_card_consideration_money": { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": "USD" | (string & {}); }; "payment_intent_id": string; "preserved_reserved_value_money": { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": "USD" | (string & {}); }; "reason": string; };
